 @Test void apiIngestCapabilityAndFullAccessAllowlistPrecedeBothManualBinders()throws Exception{String retrieve=key("retrieve",false,"trace-kb"),wrongFull=key("ingest",true,"wrong-kb"),ingest=key("ingest",false,"trace-kb");String path="/api/v1/knowledge-bases/trace-kb/knowledge/manual";machine("POST",path,retrieve,"invalid",403);machine("POST",path,wrongFull,"invalid",403);String id=machine("POST",path,ingest,"{\"content\":\"Native scoped API manual draft\",\"status\":\"draft\"}",200).path("data").path("id").asText();machine("PUT","/api/v1/knowledge/manual/"+id,retrieve,"invalid",403);machine("PUT","/api/v1/knowledge/manual/"+id,wrongFull,"invalid",403);machine("PUT","/api/v1/knowledge/manual/"+id,ingest,"{\"content\":\"Native scoped API manual published\",\"status\":\"publish\",\"process_config\":{\"summary_enabled\":false}}",200);process(id);post(id);assertEquals("completed",state(id));assertTrue(physical(id)>0);}
 @Test void imageCleanupReleasesOnlyCurrentDocumentClaimAndDeletesOnlyLastOwner()throws Exception{String ref=f.storage.forKnowledgeBase(8,"trace-kb").files().saveBytes(new byte[600],8,"shared-image.png",false);String first=create(f.callerToken,"![shared]("+ref+") old body","publish",false);process(first);post(first);String second=create(f.callerToken,"![shared]("+ref+") another owner","publish",false);process(second);post(second);f.jdbc.update("UPDATE chunks SET image_info=? WHERE knowledge_id IN (?,?) AND chunk_type='text'",json.writeValueAsString(List.of(Map.of("url",ref))),first,second);assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(DISTINCT owner_id) FROM resource_bindings WHERE resource_id=(SELECT id FROM resources WHERE handle=?)",Integer.class,ref.substring(11)));request("PUT","/api/v1/knowledge/manual/"+first,f.callerToken,"{\"content\":\"First owner removes attachment\",\"status\":\"publish\",\"process_config\":{\"summary_enabled\":false}}",200);process(first);post(first);try(var in=f.storage.forKnowledgeBase(8,"trace-kb").files().open(ref)){assertEquals(600,in.readAllBytes().length);}assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM resource_bindings WHERE resource_id=(SELECT id FROM resources WHERE handle=?)",Integer.class,ref.substring(11)));request("PUT","/api/v1/knowledge/manual/"+second,f.callerToken,"{\"content\":\"Last owner removes attachment\",\"status\":\"publish\",\"process_config\":{\"summary_enabled\":false}}",200);process(second);post(second);assertThrows(java.io.IOException.class,()->f.storage.forKnowledgeBase(8,"trace-kb").files().open(ref));assertEquals("deleted",f.jdbc.queryForObject("SELECT state FROM resources WHERE handle=?",String.class,ref.substring(11)));}

 @Test void ownedAndSharedMultimodalFanInPublishesChildrenAndEnrichmentIndexes()throws Exception{
  f.jdbc.update("UPDATE knowledge_bases SET vlm_config=?,summary_model_id='manual-summary',question_generation_config=? WHERE id='trace-kb'","{\"enabled\":true,\"model_id\":\"manual-summary\"}","{\"enabled\":true,\"question_count\":3}");
  for(String token:List.of(f.token("owner",8),f.callerToken)){
   String first="data:image/png;base64,"+Base64.getEncoder().encodeToString(new byte[600]),second="data:image/png;base64,"+Base64.getEncoder().encodeToString(new byte[601]);
   String id=create(token,"# Images\n\n![one]("+first+")\n\n![two]("+second+")", "publish",true);process(id);
   assertEquals("processing",state(id));assertEquals(2,f.jdbc.queryForObject("SELECT pending_count FROM java_image_task_pending WHERE knowledge_id=?",Long.class,id));
   assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs WHERE type='knowledge:post_process' AND json_extract(payload,'$.knowledge_id')=?",Long.class,id));
   for(int n=0;n<2;n++){var image=f.claim("multimodal");assertEquals(8,image.tenantId());assertEquals(id,image.payload().path("knowledge_id").asText());assertFalse(image.payload().path("chunk_id").asText().isEmpty());assertTrue(multimodal.execute(image,f.cancellation(image)).path("indexed").asBoolean());assertTrue(f.tasks.complete(image,json.createObjectNode()));assertEquals(1-n,f.jdbc.queryForObject("SELECT pending_count FROM java_image_task_pending WHERE knowledge_id=?",Long.class,id));}
   assertEquals(4,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND chunk_type IN ('image_ocr','image_caption')",Long.class,id));
   assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks child LEFT JOIN chunks parent ON parent.id=child.parent_chunk_id AND parent.tenant_id=child.tenant_id AND parent.knowledge_id=child.knowledge_id WHERE child.knowledge_id=? AND child.chunk_type IN ('image_ocr','image_caption') AND parent.id IS NULL",Long.class,id));
   var plan=post(id);assertTrue(plan.path("enqueued_summary").asBoolean());assertEquals(1,plan.path("enqueued_question_count").asInt());
   var q=f.claim("question");questions.execute(q,f.cancellation(q));assertTrue(f.tasks.complete(q,json.createObjectNode()));var sum=f.claim("summary");summary.execute(sum,f.cancellation(sum));assertTrue(f.tasks.complete(sum,json.createObjectNode()));
   assertEquals("completed",state(id));assertEquals(0,f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Long.class,id));assertEquals(f.count("lite_embeddings",id),physical(id));manualTrace(id);
   var stages=f.get(id,"spans",token,200).path("trace");assertEquals("done",f.node(stages,"multimodal").path("status").asText());
  }
  assertEquals(8,requests.stream().filter(r->r.path("messages").path(0).path("content").isArray()).count());
 }
 @Test void unsupportedLegacyVisionIsRejectedBeforeImagePublication()throws Exception{
  f.jdbc.update("UPDATE knowledge_bases SET vlm_config=? WHERE id='trace-kb'","{\"model_name\":\"inline-vlm\",\"base_url\":\"http://127.0.0.1/legacy\"}");String ref="data:image/png;base64,"+Base64.getEncoder().encodeToString(new byte[600]);String id=create(f.callerToken,"![legacy]("+ref+")", "publish",false);var job=f.claim("default");var failure=assertThrows(TaskFailure.class,()->manual.execute(job,f.cancellation(job)));assertFalse(failure.retryable());assertTrue(failure.getMessage().contains("legacy inline VLM"));assertEquals(0,f.count("chunks",id));assertEquals(0,f.count("lite_embeddings",id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_image_task_pending WHERE knowledge_id=?",Long.class,id));
 }

 @TestFactory java.util.stream.Stream<DynamicTest> imageProviderCannotPublishAfterCancellationOrLostSource(){return java.util.stream.Stream.of("cancel","lease","revision").map(mode->DynamicTest.dynamicTest(mode,()->{
  f.jdbc.update("UPDATE knowledge_bases SET vlm_config=? WHERE id='trace-kb'","{\"enabled\":true,\"model_id\":\"manual-summary\"}");String ref="data:image/png;base64,"+Base64.getEncoder().encodeToString(new byte[600]);String id=create(f.callerToken,"![source]("+ref+")","publish",false);process(id);var image=f.claim("multimodal");long vectors=physical(id);var once=new AtomicInteger();duringVision=()->{if(once.getAndIncrement()!=0)return;try{if(mode.equals("cancel")){var response=f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge/"+id+"/cancel-parse").header("Authorization","Bearer "+f.callerToken)).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());}else if(mode.equals("lease"))f.jdbc.update("UPDATE java_task_jobs SET lease_owner='successor' WHERE id=?",image.id());else request("PUT","/api/v1/knowledge/manual/"+id,f.callerToken,"{\"content\":\"New manual revision during VLM\",\"status\":\"draft\"}",200);}catch(Exception e){throw new RuntimeException(e);}};
  if(mode.equals("revision")){assertEquals("source_changed",multimodal.execute(image,f.cancellation(image)).path("skipped").asText());assertTrue(f.tasks.complete(image,json.createObjectNode()));assertEquals("draft",state(id));}else assertThrows(CancellationException.class,()->multimodal.execute(image,f.cancellation(image)));
  assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND chunk_type IN ('image_ocr','image_caption')",Long.class,id));assertEquals(vectors,physical(id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs WHERE type='knowledge:post_process' AND json_extract(payload,'$.knowledge_id')=?",Long.class,id));
  if(mode.equals("cancel")){assertEquals("cancelled",state(id));assertEquals("cancelled",f.get(id,"spans",f.callerToken,200).path("trace").path("status").asText());}
 }));}
 @Test void VlmProviderFailureKeepsIndexedTextAndClosesMultimodalStageThroughRealPostprocess()throws Exception{
  f.jdbc.update("UPDATE knowledge_bases SET vlm_config=? WHERE id='trace-kb'","{\"enabled\":true,\"model_id\":\"manual-summary\"}");String id=create(f.callerToken,"![source](data:image/png;base64,"+Base64.getEncoder().encodeToString(new byte[600])+")","publish",false);process(id);long vectors=physical(id);visionFailure=true;var image=f.claim("multimodal");var out=multimodal.execute(image,f.cancellation(image));assertEquals("no_extracted_content",out.path("skipped").asText());assertTrue(out.has("caption_error"));assertTrue(out.has("ocr_error"));assertTrue(f.tasks.complete(image,json.createObjectNode()));post(id);assertEquals("completed",state(id));assertEquals(vectors,physical(id));assertEquals(0,f.jdbc.queryForObject("SELECT pending_count FROM java_image_task_pending WHERE knowledge_id=?",Long.class,id));assertEquals("done",f.node(f.get(id,"spans",f.callerToken,200).path("trace"),"multimodal").path("status").asText());
 }

